func newEvent() unsafe.Pointer { return unsafe.Pointer(new(watchtower.Event)) }

func newNEvent(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]watchtower.Event, n)))
}

func ptrEvent(p unsafe.Pointer, c int32) any {
	r := (*watchtower.Event)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ItemID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 5:
		return (*string)(unsafe.Pointer(&r.ActorID))
	case 6:
		return &r.FromValue
	case 7:
		return &r.ToValue
	case 8:
		return &r.Note
	case 9:
		return &r.CreatedAt
	}
	return nil
}

func valueEvent(p unsafe.Pointer, c int32) any {
	r := (*watchtower.Event)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ItemID)
	case 4:
		return string(r.Kind)
	case 5:
		if r.ActorID == "" {
			return nil
		}
		return string(r.ActorID)
	case 6:
		if r.FromValue == "" {
			return nil
		}
		return r.FromValue
	case 7:
		if r.ToValue == "" {
			return nil
		}
		return r.ToValue
	case 8:
		if r.Note == "" {
			return nil
		}
		return r.Note
	case 9:
		return r.CreatedAt
	}
	return nil
}

