func newRead() unsafe.Pointer { return unsafe.Pointer(new(watchtower.Read)) }

func newNRead(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]watchtower.Read, n)))
}

func ptrRead(p unsafe.Pointer, c int32) any {
	r := (*watchtower.Read)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ItemID))
	case 1:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 4:
		return &r.SeenAt
	}
	return nil
}

func valueRead(p unsafe.Pointer, c int32) any {
	r := (*watchtower.Read)(p)
	switch c {
	case 0:
		return string(r.ItemID)
	case 1:
		return string(r.UserID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.OrganizationID)
	case 4:
		return r.SeenAt
	}
	return nil
}

